SLOT_TRANSITIONS = {"AVAILABLE": {"TEMP_HOLD", "MAINTENANCE", "RESERVED"}, "TEMP_HOLD": {"AVAILABLE", "BOOKED"}, "BOOKED": {"AVAILABLE", "OCCUPIED"}, "OCCUPIED": {"OVERSTAY", "AVAILABLE", "DISPUTED"}, "OVERSTAY": {"AVAILABLE", "DISPUTED"}, "RESERVED": {"AVAILABLE"}, "MAINTENANCE": {"AVAILABLE"}, "DISPUTED": {"AVAILABLE", "OCCUPIED"}}
BOOKING_TRANSITIONS = {"INITIATED": {"ENTRY_PAID_CONFIRMED", "CANCELLED", "EXPIRED"}, "ENTRY_PAID_CONFIRMED": {"CHECKED_IN", "CANCELLED", "EXPIRED"}, "CHECKED_IN": {"EXTENDED", "EXIT_PENDING_PAYMENT", "SETTLED_EXITED"}, "EXTENDED": {"EXTENDED", "EXIT_PENDING_PAYMENT", "SETTLED_EXITED"}, "EXIT_PENDING_PAYMENT": {"SETTLED_EXITED"}}

def transition(table: dict, current: str, target: str) -> str:
    if target not in table.get(current, set()):
        raise ValueError(f"Illegal transition: {current} -> {target}")
    return target
